-- PostgreSQL 15+; synthetic inventory only.
CREATE SCHEMA IF NOT EXISTS ict_demo;
CREATE TABLE IF NOT EXISTS ict_demo.service_owners(owner_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,owner_code TEXT NOT NULL UNIQUE,owner_label TEXT NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS ict_demo.services(service_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,service_code TEXT NOT NULL UNIQUE,service_name TEXT NOT NULL,service_tier TEXT NOT NULL CHECK(service_tier IN('critical','high','standard','low')),owner_id BIGINT NOT NULL REFERENCES ict_demo.service_owners(owner_id) ON DELETE RESTRICT,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('planned','active','degraded','retired')),support_hours TEXT NOT NULL DEFAULT 'business_hours');
CREATE TABLE IF NOT EXISTS ict_demo.assets(asset_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,asset_ref TEXT NOT NULL UNIQUE,service_id BIGINT REFERENCES ict_demo.services(service_id) ON DELETE RESTRICT,asset_type TEXT NOT NULL CHECK(asset_type IN('server','endpoint','network_device','software','database','other')),environment TEXT NOT NULL CHECK(environment IN('development','test','staging','production')),sensitivity TEXT NOT NULL CHECK(sensitivity IN('public_metadata','internal','restricted_metadata')),lifecycle TEXT NOT NULL DEFAULT 'active' CHECK(lifecycle IN('planned','active','maintenance','retired')),purchased_on DATE,retire_on DATE);
CREATE TABLE IF NOT EXISTS ict_demo.work_items(item_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,item_ref TEXT NOT NULL UNIQUE,service_id BIGINT REFERENCES ict_demo.services(service_id) ON DELETE RESTRICT,item_type TEXT NOT NULL CHECK(item_type IN('incident','change','maintenance','request')),summary TEXT NOT NULL,priority SMALLINT NOT NULL CHECK(priority BETWEEN 1 AND 5),status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','in_progress','blocked','resolved','cancelled')),opened_at TIMESTAMPTZ NOT NULL DEFAULT now(),due_at TIMESTAMPTZ,resolved_at TIMESTAMPTZ,owner_ref TEXT NOT NULL,CHECK(status<>'resolved' OR resolved_at IS NOT NULL));
CREATE TABLE IF NOT EXISTS ict_demo.work_events(event_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,item_id BIGINT NOT NULL REFERENCES ict_demo.work_items(item_id) ON DELETE RESTRICT,previous_status TEXT,new_status TEXT NOT NULL CHECK(new_status IN('open','in_progress','blocked','resolved','cancelled')),note TEXT NOT NULL,actor_ref TEXT NOT NULL,happened_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_ict_services_owner ON ict_demo.services(owner_id,status);
CREATE INDEX IF NOT EXISTS ix_ict_assets_lifecycle ON ict_demo.assets(lifecycle,environment);
CREATE INDEX IF NOT EXISTS ix_ict_work_queue ON ict_demo.work_items(status,priority DESC,due_at);
CREATE INDEX IF NOT EXISTS ix_ict_events_item ON ict_demo.work_events(item_id,happened_at DESC,event_id DESC);